import{_ as e,c as r,o as h,af as i}from"./chunks/framework.BKeRpnBD.js";const p=JSON.parse('{"title":"8、【比】 坤下坎上","description":"横渠易说 - 8、【比】 坤下坎上","frontmatter":{"title":"8、【比】 坤下坎上","description":"横渠易说 - 8、【比】 坤下坎上"},"headers":[],"relativePath":"zh/classics/hengqu/010.md","filePath":"zh/classics/hengqu/010.md"}'),l={name:"zh/classics/hengqu/010.md"};function t(n,a,s,d,c,o){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="_8、【比】-坤下坎上" tabindex="-1">8、【比】 坤下坎上 <a class="header-anchor" href="#_8、【比】-坤下坎上" aria-label="Permalink to “8、【比】 坤下坎上”">​</a></h1><h3 id="彖曰-比吉-也-比-辅也-下顺从也。-原筮元永贞无咎-以刚中也。-不宁方来-上下应也。-后夫凶-其道穷也。" tabindex="-1">彖曰：“比吉”也，比，辅也，下顺从也。“原筮元永贞无咎”，以刚中也。“不宁方来”，上下应也。“后夫凶”，其道穷也。 <a class="header-anchor" href="#彖曰-比吉-也-比-辅也-下顺从也。-原筮元永贞无咎-以刚中也。-不宁方来-上下应也。-后夫凶-其道穷也。" aria-label="Permalink to “彖曰：“比吉”也，比，辅也，下顺从也。“原筮元永贞无咎”，以刚中也。“不宁方来”，上下应也。“后夫凶”，其道穷也。”">​</a></h3><h3 id="象曰-地上有水-比-先王以建万国-亲诸侯。" tabindex="-1">象曰：地上有水，比，先王以建万国，亲诸侯。 <a class="header-anchor" href="#象曰-地上有水-比-先王以建万国-亲诸侯。" aria-label="Permalink to “象曰：地上有水，比，先王以建万国，亲诸侯。”">​</a></h3><p>必原筮者，慎所与也。</p><h3 id="初六-有孚比之-无咎。有孚盈缶-终来有它-吉。-象曰-比之初六-有它吉也。" tabindex="-1">初六，有孚比之，无咎。有孚盈缶，终来有它，吉。 象曰：比之初六，有它吉也。 <a class="header-anchor" href="#初六-有孚比之-无咎。有孚盈缶-终来有它-吉。-象曰-比之初六-有它吉也。" aria-label="Permalink to “初六，有孚比之，无咎。有孚盈缶，终来有它，吉。 象曰：比之初六，有它吉也。”">​</a></h3><p>柔而无应，能择有信者亲之，己之诚素着显，终有它吉，比好先也。</p><h3 id="六二-比之自内-贞吉。-象曰-比之自内-不自失也。" tabindex="-1">六二，比之自内，贞吉。 象曰：“比之自内”，不自失也。 <a class="header-anchor" href="#六二-比之自内-贞吉。-象曰-比之自内-不自失也。" aria-label="Permalink to “六二，比之自内，贞吉。 象曰：“比之自内”，不自失也。”">​</a></h3><p>爱自亲始，人道之正，故曰“贞吉”。</p><h3 id="六三-比之匪人。-象曰-比之匪人-不亦伤乎" tabindex="-1">六三，比之匪人。 象曰：“比之匪人”，不亦伤乎! <a class="header-anchor" href="#六三-比之匪人。-象曰-比之匪人-不亦伤乎" aria-label="Permalink to “六三，比之匪人。 象曰：“比之匪人”，不亦伤乎!”">​</a></h3><p>履非其正，比之必匪其人，故可伤。</p><h3 id="六四-外比之-贞吉。-象曰-外比于贤-以从上也。" tabindex="-1">六四，外比之，贞吉。 象曰：外比于贤，以从上也。 <a class="header-anchor" href="#六四-外比之-贞吉。-象曰-外比于贤-以从上也。" aria-label="Permalink to “六四，外比之，贞吉。 象曰：外比于贤，以从上也。”">​</a></h3><h3 id="九五-显比-王用三驱失前禽-邑人不诫-吉。-象曰-显比之吉-位正中也。舍逆取顺-失前禽也。-邑人不诫-上使中也。" tabindex="-1">九五，显比，王用三驱失前禽，邑人不诫，吉。 象曰：显比之吉，位正中也。舍逆取顺，失前禽也。“邑人不诫”，上使中也。 <a class="header-anchor" href="#九五-显比-王用三驱失前禽-邑人不诫-吉。-象曰-显比之吉-位正中也。舍逆取顺-失前禽也。-邑人不诫-上使中也。" aria-label="Permalink to “九五，显比，王用三驱失前禽，邑人不诫，吉。 象曰：显比之吉，位正中也。舍逆取顺，失前禽也。“邑人不诫”，上使中也。”">​</a></h3><h3 id="上六-比之无首-凶。-象曰-比之无首-无所终也。" tabindex="-1">上六，比之无首，凶。 象曰：“比之无首”，无所终也。 <a class="header-anchor" href="#上六-比之无首-凶。-象曰-比之无首-无所终也。" aria-label="Permalink to “上六，比之无首，凶。 象曰：“比之无首”，无所终也。”">​</a></h3><p>失前禽，谓三面而驱，意在缓逸之，不务杀也。顺奔然后取之，故被伤者少也。 以刚居中而显明比道，伐止有罪，不为滥刑，故邑人不诫，为上用中，此之谓也。不比者不惩，非用中也，故比必显之，然杀不可务也。一云：上使中者，付得其人也。</p>',14)])])}const b=e(l,[["render",t]]);export{p as __pageData,b as default};
